package Twilio::Generator::Emit;

use 5.016;
use warnings;

use Twilio::Generator::Pod;

our $VERSION = '2.001';

# The layout does not matter here, because the result goes through perltidy.
sub module {
  my ($model) = @_;
  return join "\n", _header($model), _list($model), _page($model), _context($model),
    _instance($model), _answer_classes($model), "1;\n", '__END__', q{},
    Twilio::Generator::Pod::document($model);
}

sub _header {
  my ($model) = @_;
  return <<"END_CODE";
# Generated by tools/generate.pl from Twilio's OpenAPI specs. Do not edit this file.
package $model->{module};

use 5.016;
use warnings;

our \$VERSION = '2.001';
END_CODE
}

sub _list {
  my ($model) = @_;
  my $side = $model->{list} or return q{};

  my @methods = (_constructor($side));
  push @methods, _list_body_method($model, 'create')             if $side->{create};
  push @methods, _delete_method($model, $side->{delete}, 'list') if $side->{delete};
  push @methods, _fetch_method($model, $side, 'list')            if $side->{fetch};
  push @methods, _reading($model)                                if $side->{read};
  push @methods, _list_body_method($model, 'update')             if $side->{update};
  push @methods, _get_context($model) if ($model->{context} // {})->{own};
  push @methods, map { _child_method($side, $_) } @{ $side->{children} // [] };

  return join "\n", "package $model->{class}{list};\n", "use parent 'Twilio::ListResource';\n",
    "use Twilio::Serialize;\n", @methods;
}

# A list has no instance URI of its own to fetch, and answers with the object itself, as the
# account balance does.
sub _fetch_method {
  my ($model, $side, $where) = @_;

  my @options   = @{ $side->{fetch}{options} };
  my $signature = join q{, }, '$self', @options ? '$options' : ();
  my $defaults  = @options ? "  \$options //= {};\n" : q{};
  my @parts     = _request_parts(_pairs_by_place($side->{fetch}), $side->{fetch});
  my $extra     = @parts ? ', { ' . join(q{, }, @parts) . ' }' : q{};
  my $returned  = _returned($side->{fetch}, _instance_code($model, $side, $where));

  return <<"END_CODE";
sub fetch {
  my ($signature) = \@_;
$defaults
  my \$response = \$self->{version}->handle_request('$side->{fetch}{method}', \$self->{uri}, 'fetch'$extra);
$returned}
END_CODE
}

sub _instance_code {
  my ($model, $side, $where) = @_;
  return '$self->_build_instance($response)' if $where ne 'list';
  return _new_instance($model, '$response->get_content', $side->{parameters});
}

# What a method returns: true when Twilio answers with no body, or else what it answers with,
# chosen by status code when that can be more than one kind of object.
sub _returned {
  my ($operation, $instance) = @_;

  my $result  = $operation->{result} or return "  return 1;\n";
  my @others  = @{ $result->{others} };
  my $payload = '$self->{version}, $response->get_content';
  my $final =
    $result->{instance}
    ? "  return $instance;\n"
    : '  return ' . (pop @others)->{class} . "->new($payload);\n";

  my @chosen;
  for my $other (@others) {
    my $test = join q{ || }, map { "\$status == $_" } @{ $other->{codes} };
    push @chosen, "  return $other->{class}->new($payload) if $test;\n";
  }
  return $final if !@chosen;
  return join q{}, "  my \$status = \$response->get_status_code;\n", @chosen, $final;
}

sub _delete_method {
  my ($model, $operation, $where) = @_;

  my @options = @{ $operation->{options} // [] };
  my @parts   = _request_parts(_pairs_by_place($operation), $operation);
  my $extra   = @parts ? ', { ' . join(q{, }, @parts) . ' }' : q{};
  my $start =
    @options ? "  my (\$self, \$options) = \@_;\n  \$options //= {};\n" : "  my (\$self) = \@_;\n";
  my $request =
    "\$self->{version}->handle_request('$operation->{method}', \$self->{uri}, 'delete'$extra)";

  if (!$operation->{result}) {
    return "sub delete {\n$start  $request;\n  return 1;\n}\n";
  }
  my $side = $where eq 'list' ? $model->{list} : $model->{context};
  return
    "sub delete {\n$start  my \$response = $request;\n"
    . _returned($operation, _instance_code($model, $side, $where)) . "}\n";
}

sub _new_instance {
  my ($model, $payload, $names) = @_;

  my $arguments = join q{, }, '$self->{version}', $payload,
    map { "\$self->{solution}{$_}" } @{$names};
  return "$model->{class}{instance}->new($arguments)";
}

# A child whose URL has ids its parent does not hold, like Voice's /Archives/{Date}/Calls/{Sid},
# takes them first, in the order of the URL: archived_calls($date, $sid).
sub _child_method {
  my ($side, $child) = @_;

  my @extra     = map { "\$$_" } @{ $child->{extra_ids} // [] };
  my @held      = @{ $side->{parameters} };
  my $used      = $child->{used_ids} // scalar @held;
  my $arguments = join q{, }, $side->{owner} // '$self->{version}',
    (map { "\$self->{solution}{$_}" } @held[0 .. $used - 1]), @extra;
  my $load = "  require $child->{module};\n";

  my $own       = $child->{own};
  my $signature = join q{, }, '$self', @extra, defined $own && !$child->{singleton} ? "\$$own" : ();
  my $start     = "sub $child->{mount} {\n  my ($signature) = \@_;\n$load";

  return "$start  return $child->{context}->new($arguments);\n}\n" if $child->{singleton};
  return "$start  return $child->{list}->new($arguments);\n}\n"    if !defined $own;
  return <<"END_CODE";
$start  my \$list = $child->{list}->new($arguments);
  return defined \$$own ? \$list->get_context(\$$own) : \$list;
}
END_CODE
}

sub _constructor {
  my ($side) = @_;

  my @names     = @{ $side->{parameters} };
  my $signature = join q{, }, '$class', '$version', map { "\$$_" } @names;
  my $solution  = join q{, }, map { "$_ => \$$_" } @names;
  my $uri       = _uri_expression($side->{uri});

  return <<"END_CODE";
sub new {
  my ($signature) = \@_;
  my \$self = \$class->SUPER::new(\$version);
  \$self->{solution} = { $solution };
  \$self->{uri} = $uri;
  return \$self;
}
END_CODE
}

sub _uri_expression {
  my ($uri) = @_;

  my @pieces = map {
        defined $_->{literal} ? _quoted($_->{literal})
      : defined $_->{writer}
      ? "Twilio::Serialize::path_segment(Twilio::Serialize::$_->{writer}(\$$_->{parameter}))"
      : "Twilio::Serialize::path_segment(\$$_->{parameter})"
  } @{$uri};
  return @pieces == 1 ? $pieces[0] : join q{, }, 'join q{}', @pieces;
}

sub _quoted {
  my ($text) = @_;
  $text =~ s/([\\'])/\\$1/g;
  return "'$text'";
}

# A list has no instance URI of its own, so what it creates or updates is built from the list's ids.
sub _list_body_method {
  my ($model, $verb) = @_;
  my $operation = $model->{list}{$verb};
  my $returned  = _returned($operation, _instance_code($model, $model->{list}, 'list'));
  return _body_method($verb, $operation) . "$returned}\n";
}

# Ends just after the request, so each caller only adds how the result is returned.
# A JSON body comes as one hash reference, after the required values and before the options.
sub _body_method {
  my ($verb, $operation) = @_;

  my $json      = $operation->{json};
  my @required  = map { _variable($_->{name}) } @{ $operation->{required} };
  my @options   = @{ $operation->{options} };
  my $signature = join q{, }, '$self', @required, $json ? '$body' : (), @options ? '$options' : ();
  my $defaults  = @options ? "  \$options //= {};\n" : q{};

  my $pairs = _pairs_by_place($operation);
  my $data =
    $json
    ? '  my $data = Twilio::Serialize::json_body($body, ' . _rules_code($json->{rules}) . ");\n"
    : "  my \$data = {\n" . join(q{}, map { "$_,\n" } @{ $pairs->{body} // [] }) . "  };\n";
  my $extra = join q{}, map { ", $_" } _request_parts($pairs, $operation);

  return <<"END_CODE";
sub $verb {
  my ($signature) = \@_;
$defaults
$data
  my \$response = \$self->{version}->handle_request('$operation->{method}', \$self->{uri}, '$verb', { data => \$data$extra });
END_CODE
}

# A required value named like a variable of the method itself, as Sync's Data is, gets a name
# of its own in the code. The documentation keeps the name.
my %IS_LOCAL = map { $_ => 1 } qw(arguments data options response self);

sub _variable {
  my ($name) = @_;
  return $IS_LOCAL{$name} ? "\$${name}_value" : "\$$name";
}

# Each argument as code, by where it goes: the body, the query string or the headers.
sub _pairs_by_place {
  my ($operation) = @_;

  my %pairs;
  push @{ $pairs{ $_->{place} } }, _pair($_, _variable($_->{name}))
    for @{ $operation->{required} // [] };
  push @{ $pairs{ $_->{place} } }, _pair($_, "\$options->{$_->{name}}")
    for @{ $operation->{options} // $operation->{filters} // [] };
  return \%pairs;
}

# What a request sends besides its body. A JSON body says so in its headers, and SCIM answers
# are asked for by name, as twilio-php does.
sub _request_parts {
  my ($pairs, $operation) = @_;

  my @headers = @{ $pairs->{header} // [] };
  unshift @headers, q{    'Content-Type' => 'application/json'}      if $operation->{json};
  unshift @headers, '    Accept => ' . _quoted($operation->{accept}) if $operation->{accept};

  my @parts;
  push @parts, 'params => { ' . join(q{}, map { "$_,\n" } @{ $pairs->{query} }) . ' }'
    if $pairs->{query};
  push @parts, 'headers => { ' . join(q{}, map { "$_,\n" } @headers) . ' }' if @headers;
  return @parts;
}

sub _rules_code {
  my ($rules) = @_;
  my @pairs = map { _quoted($_) . ' => ' . _quoted($rules->{$_}) } sort keys %{$rules};
  return '{ ' . join(q{, }, @pairs) . ' }';
}

sub _pair {
  my ($argument, $value) = @_;

  # Its own name is never sent: each key becomes a parameter, as in AddOns.lookup.Key.
  my $prefix = $argument->{map_prefix};
  if (defined $prefix) {
    return
        '    %{ Twilio::Serialize::prefixed_collapsible_map('
      . "$value, "
      . _quoted($prefix) . ') }';
  }

  my $wire   = $argument->{wire} =~ /\A\w+\z/ ? $argument->{wire} : _quoted($argument->{wire});
  my $writer = $argument->{writer};
  my $written =
      !defined $writer   ? $value
    : $argument->{array} ? "Twilio::Serialize::map_values($value, \\&Twilio::Serialize::$writer)"
    :                      "Twilio::Serialize::$writer($value)";
  return "    $wire => $written";
}

sub _reading {
  my ($model) = @_;

  # A required filter is taken first, and kept with the other options, so that page has it too.
  my $operation = $model->{list}{read};
  my @required  = map { $_->{name} } @{ $operation->{required} // [] };
  my $pairs =
    _pairs_by_place({ filters => [@{ $operation->{required} // [] }, @{ $operation->{filters} }] });

  # The v1.0 standard pages by token alone, under these camelCase names, as twilio-python sends
  # them. twilio-php sends PageSize there too, which these APIs do not read.
  my @paging =
    $model->{v1_standard}
    ? ('    pageSize => $page_size', '    pageToken => $page_token')
    : ('    PageToken => $page_token', '    Page => $page_number', '    PageSize => $page_size');
  my $page_arguments = join q{, }, '$self', '$options', '$page_size', '$page_token',
    $model->{v1_standard} ? () : '$page_number';
  my $params = join q{}, map { "$_,\n" } @{ $pairs->{query} // [] }, @paging;
  my @parts  = _request_parts({ header => $pairs->{header} }, $operation);
  my $extra  = join q{}, map { ", $_" } @parts;

  my $taken     = join q{}, map { q{, } . _variable($_) } @required;
  my $arguments = @required ? '$options, @arguments' : '@arguments';
  my $forwarded =
    @required
    ? '{ %{ $options // {} }, '
    . join(q{, }, map { "$_ => " . _variable($_) } @required)
    . ' }, @arguments'
    : '@arguments';

  my $code = <<"END_CODE";
sub read {
  my (\$self$taken, $arguments) = \@_;
  return \$self->read_records($forwarded);
}

sub stream {
  my (\$self$taken, $arguments) = \@_;
  return \$self->stream_records($forwarded);
}

sub page {
  my ($page_arguments) = \@_;
  \$options //= {};

  my \$params = {
$params  };

  my \$response = \$self->{version}->page('$operation->{method}', \$self->{uri}, { params => \$params$extra });
  return \$self->_build_page(\$response);
}

sub get_page {
  my (\$self, \$target_url) = \@_;
  my \$client = \$self->{version}->get_domain->get_client;
  return \$self->_build_page(\$client->request('GET', \$target_url));
}

sub _build_page {
  my (\$self, \$response) = \@_;
  return $model->{class}{page}->new(\$self->{version}, \$response, \$self->{solution});
}
END_CODE
  return $code;
}

sub _get_context {
  my ($model)   = @_;
  my $own       = $model->{context}{own};
  my $arguments = join q{, }, '$self->{version}',
    (map { "\$self->{solution}{$_}" } @{ $model->{list}{parameters} }),
    "\$$own";

  return <<"END_CODE";
sub get_context {
  my (\$self, \$$own) = \@_;
  return $model->{class}{context}->new($arguments);
}
END_CODE
}

sub _page {
  my ($model) = @_;
  return q{} if !defined $model->{records_key};

  my $result = _new_instance($model, '$payload', $model->{list}{parameters});
  my $parent = $model->{v1_standard} ? 'Twilio::TokenPaginationPage' : 'Twilio::Page';
  return <<"END_CODE";
package $model->{class}{page};

use parent '$parent';

sub records_key { return '$model->{records_key}' }

sub build_instance {
  my (\$self, \$payload) = \@_;
  return $result;
}
END_CODE
}

sub _context {
  my ($model) = @_;
  my $side = $model->{context} or return q{};

  my @methods = (_constructor($side));
  push @methods, _context_body_method($side, 'create')              if $side->{create};
  push @methods, _delete_method($model, $side->{delete}, 'context') if $side->{delete};
  push @methods, _fetch_method($model, $side, 'context')            if $side->{fetch};
  push @methods, _context_body_method($side, $_) for grep { $side->{$_} } qw(patch update);

  if (grep { (($side->{$_} // {})->{result} // {})->{instance} }
    qw(create delete fetch patch update))
  {
    my $result = _new_instance($model, '$response->get_content', $side->{parameters});
    push @methods, <<"END_CODE";
sub _build_instance {
  my (\$self, \$response) = \@_;
  return $result;
}
END_CODE
  }
  push @methods, map { _child_method($side, $_) } @{ $side->{children} // [] };

  return join "\n", "package $model->{class}{context};\n",
    "use parent 'Twilio::InstanceContext';\n", "use Twilio::Serialize;\n", @methods;
}

sub _context_body_method {
  my ($side, $verb) = @_;
  my $returned = _returned($side->{$verb}, '$self->_build_instance($response)');
  return _body_method($verb, $side->{$verb}) . "$returned}\n";
}

sub _instance {
  my ($model) = @_;
  return q{} if !$model->{has_instance};

  my @names     = @{ ($model->{context} // $model->{list})->{parameters} };
  my $own       = ($model->{context} // {})->{own};
  my $own_field = ($model->{context} // {})->{own_field} // $own;

  my @pairs =
    map {
    defined $own && $_ eq $own ? "$_ => \$$_ // \$self->{properties}{$own_field}" : "$_ => \$$_"
    } @names;
  my $signature = join q{, }, '$class', '$version', '$payload', map { "\$$_" } @names;
  my $solution  = join q{, }, @pairs;

  my @code = (<<"END_CODE");
package $model->{class}{instance};

use parent 'Twilio::InstanceResource';

use Twilio::Deserialize;

sub new {
  my ($signature) = \@_;
  my \$self = \$class->SUPER::new(\$version, \$payload);
  \$self->{solution} = { $solution };
  return \$self;
}
END_CODE

  push @code, _context_shortcuts($model) if $model->{context};
  push @code, join q{}, map { _accessor($_) } @{ $model->{fields} };
  return join "\n", @code;
}

sub _context_shortcuts {
  my ($model) = @_;

  my $side = $model->{context};
  my @code;
  for my $verb (grep { $side->{$_} } qw(create delete fetch patch update)) {
    push @code, <<"END_CODE";
sub $verb {
  my (\$self, \@arguments) = \@_;
  return \$self->_context->$verb(\@arguments);
}
END_CODE
  }

  for my $child (@{ $side->{children} // [] }) {
    push @code, <<"END_CODE";
sub $child->{mount} {
  my (\$self, \@arguments) = \@_;
  return \$self->_context->$child->{mount}(\@arguments);
}
END_CODE
  }

  my $arguments = join q{, }, '$self->{version}',
    map { "\$self->{solution}{$_}" } @{ $side->{parameters} };
  push @code, <<"END_CODE";
sub _context {
  my (\$self) = \@_;
  return $model->{class}{context}->new($arguments);
}
END_CODE
  return join "\n", @code;
}

# An object that is not the resource, like an acknowledgment, has fields and nothing else.
sub _answer_classes {
  my ($model) = @_;

  my @code;
  for my $answer (@{ $model->{answer_classes} // [] }) {
    push @code, join q{}, <<"END_CODE", map { _accessor($_) } @{ $answer->{fields} };
package $answer->{class};

use parent 'Twilio::InstanceResource';

use Twilio::Deserialize;

END_CODE
  }
  return @code;
}

sub _accessor {
  my ($field) = @_;

  my $value = "\$_[0]{properties}{$field->{name}}";
  $value = "Twilio::Deserialize::$field->{reader}($value)" if defined $field->{reader};
  return "sub $field->{method} { return $value }\n";
}

sub version {
  my ($top) = @_;

  my $class = $top->{version_class};
  my $roots = join "\n",
    map { _child_method({ parameters => [], owner => '$self' }, $_) } @{ $top->{roots} };

  # twilio-php wraps the version in an ApiV1Version in each class of these APIs. Inheriting from
  # it here gives every request the same errors.
  my $parent = $top->{v1_standard} ? 'Twilio::ApiV1Version' : 'Twilio::Version';
  my $code   = <<"END_CODE";
# Generated by tools/generate.pl from Twilio's OpenAPI specs. Do not edit this file.
package $class;

use 5.016;
use warnings;

use parent '$parent';

our \$VERSION = '2.001';

sub new {
  my (\$class, \$domain) = \@_;
  my \$self = \$class->SUPER::new(\$domain);
  \$self->{version} = '$top->{version_path}';
  return \$self;
}

# Each of these objects is built on demand, for the reason given in Twilio::Rest::Client.
$roots
END_CODE

  my @pod = (
    $class,
    'Version '
      . (length $top->{version_path} ? $top->{version_path} : $top->{version_method})
      . ' of the Twilio REST API',
    "See L<$parent> for the inherited methods."
  );
  return $code . _pod_shortcuts(@pod, $top->{roots}) if !$top->{account_context};

  $code .= <<"END_CODE";
sub account {
  my (\$self) = \@_;
  require $top->{account_module};
  return $top->{account_context}->new(\$self, \$self->get_domain->get_client->get_account_sid);
}

END_CODE

  $code .= _forwarders($top->{shortcuts}, '$self->account');
  return $code
    . _pod_shortcuts(
    @pod,
    ['accounts', "Returns the list of accounts, or the context of one account."],
    ['account',  "Returns the context of the client's account."],
    $top->{shortcuts},
    );
}

sub domain {
  my ($domain) = @_;

  my $class    = $domain->{class};
  my $versions = join "\n", map { _version_method($_) } @{ $domain->{versions} };
  my $code     = <<"END_CODE";
# Generated by tools/generate.pl from Twilio's OpenAPI specs. Do not edit this file.
package $class;

use 5.016;
use warnings;

use parent 'Twilio::Domain';

our \$VERSION = '2.001';

sub new {
  my (\$class, \$client) = \@_;
  my \$self = \$class->SUPER::new(\$client);
  \$self->{base_url} = '$domain->{base_url}';
  return \$self;
}

$versions
END_CODE

  my @pod = (
    $class,
    "The $domain->{base_url} host",
    "See L<Twilio::Domain> for the inherited methods.",
    map { [$_->{version_method}, "Returns L<$_->{version_class}>."] } @{ $domain->{versions} }
  );
  my $main = $domain->{main};
  if (!$main) {
    my $shortcuts = $domain->{shortcuts} // [];
    $code .= join "\n", map { _forwarders([$_], "\$self->$_->{version_method}") } @{$shortcuts};
    return $code . _pod_shortcuts(@pod, $shortcuts);
  }

  my @forwarded = ({ mount => 'accounts' }, { mount => 'account' }, @{ $main->{shortcuts} });
  $code .= _forwarders(\@forwarded, "\$self->$main->{version_method}");
  return $code
    . _pod_shortcuts(
    @pod,
    ['accounts', "Returns the list of accounts, or the context of one account."],
    ['account',  "Returns the context of the client's account."],
    $main->{shortcuts},
    );
}

sub _version_method {
  my ($top) = @_;
  return <<"END_CODE";
sub $top->{version_method} {
  my (\$self) = \@_;
  require $top->{version_class};
  return $top->{version_class}->new(\$self);
}
END_CODE
}

sub client {
  my ($domains) = @_;

  my ($top) = map { $_->{main} // () } @{$domains};
  my $code = <<"END_CODE";
# Generated by tools/generate.pl from Twilio's OpenAPI specs. Do not edit this file.
package Twilio::Rest::Client;

use 5.016;
use warnings;

use parent 'Twilio::Base::BaseClient';

our \$VERSION = '2.001';

# twilio-php caches these objects. Here each is built on demand: a child holds its parent, so
# a parent that also held its child would be a reference cycle, which Perl never frees, and
# long-running processes would leak every client they create. Requiring on demand keeps
# startup fast when hundreds of resources exist.
END_CODE

  $code .= join "\n", map { _domain_method($_) } @{$domains};
  $code .= "\n" . _forwarders([{ mount => 'account' }, @{ $top->{shortcuts} }], '$self->api');
  return $code . _pod_client($top, $domains);
}

sub _domain_method {
  my ($domain) = @_;
  return <<"END_CODE";
sub $domain->{method} {
  my (\$self) = \@_;
  require $domain->{class};
  return $domain->{class}->new(\$self);
}
END_CODE
}

sub _forwarders {
  my ($shortcuts, $target) = @_;

  return join "\n", map { <<"END_CODE" } @{$shortcuts}, ();
sub $_->{mount} {
  my (\$self, \@arguments) = \@_;
  return $target->$_->{mount}(\@arguments);
}
END_CODE
}

sub _pod_shortcuts {
  my ($class, $title, $intro, @entries) = @_;

  my $shortcuts = pop @entries;
  my @pod       = (
    "\n1;\n",
    "__END__\n",
    "=encoding UTF-8\n",
    "=head1 NAME\n",
    "$class - $title\n",
    "=head1 DESCRIPTION\n",
    "$intro\n",
    "=head1 METHODS\n",
    "=head2 new\n",
    "  my \$object = $class->new(\$parent);\n",
  );
  push @pod, map { ("=head2 $_->[0]\n", "$_->[1]\n") } @entries;
  push @pod, _pod_shortcut_entries($shortcuts);
  return join "\n", @pod, Twilio::Generator::Pod::end();
}

sub _pod_shortcut_entries {
  my ($shortcuts) = @_;
  return map { ("=head2 $_->{mount}\n", "See L<$_->{module}>.\n") } @{$shortcuts};
}

sub _pod_domain {
  my ($domain) = @_;

  my $purpose = $domain->{main} ? ', the domain of the main API' : q{};
  return ("=head2 $domain->{method}\n", "Returns L<$domain->{class}>$purpose.\n");
}

sub _pod_client {
  my ($top, $domains) = @_;

  return join "\n", "\n1;\n", "__END__\n", "=encoding UTF-8\n", "=head1 NAME\n",
    "Twilio::Rest::Client - Client for the Twilio REST API\n", <<'END_POD',
=head1 SYNOPSIS

  use Twilio::Rest::Client;

  my $client = Twilio::Rest::Client->new($account_sid, $auth_token);

  # With an API key, which is what Twilio recommends for applications
  my $client = Twilio::Rest::Client->new($api_key_sid, $api_key_secret, {
    account_sid => $account_sid,
  });

  my $message = $client->messages->create('+15558675309', {
    from => '+15017250604',
    body => 'Hello',
  });

=head1 DESCRIPTION

The entry point to the Twilio API. Credentials, routing and low-level requests
are described in L<Twilio::Base::BaseClient>.

Each resource of the account has a method here. It returns the list of the
resource, or, given an identifier, the context of one record. The same methods
exist on the object from C<account>, which takes another account from
C<< $client->api->accounts($sid) >>.

=head1 METHODS
END_POD
    map({ _pod_domain($_) } @{$domains}), <<'END_POD',
=head2 account

Returns the context of the client's account. See
L<Twilio::Rest::Api::V2010::Account>.
END_POD
    _pod_shortcut_entries($top->{shortcuts}), Twilio::Generator::Pod::end();
}

1;
